import { useState } from 'react';

// ❌ OLD: Typing in the input triggers a heavy filter synchronously.
// Every keystroke lags because the input value update competes
// directly with rendering 5,000 complex list items.
export default function Search({ allItems }) {
  const [query, setQuery] = useState('');
  const [filtered, setFiltered] = useState(allItems);

  function handleChange(e) {
    const val = e.target.value;
    setQuery(val); // Urgent update
    setFiltered(allItems.filter(item => item.name.includes(val))); // ❌ Heavy blocking update
  }

  return (
    <div>
      <input value={query} onChange={handleChange} />
      <ul>{filtered.map(i => <li key={i.id}>{i.name}</li>)}</ul>
    </div>
  );
}

import { useState, useTransition } from 'react';

// ✅ NEW: Keep input typing in the urgent lane (0ms lag)
// while deferring the heavy list re-render in a transition lane.
export default function Search({ allItems }) {
  const [query, setQuery] = useState('');
  const [filtered, setFiltered] = useState(allItems);
  const [isPending, startTransition] = useTransition();

  function handleChange(e) {
    const val fresh = e.target.value;
    setQuery(val fresh); // Urgent: updates input immediately

    startTransition(() => {
      // Non-urgent: can be interrupted by subsequent keystrokes
      setFiltered(allItems.filter(item => item.name.includes(val fresh)));
    });
  }

  return (
    <div>
      <input value={query} onChange={handleChange} />
      {isPending && <span className="spinner">Updating list...</span>}
      <ul style={{ opacity: isPending ? 0.7 : 1 }}>
        {filtered.map(i => <li key={i.id}>{i.name}</li>)}
      </ul>
    </div>
  );
}
